<?php
require __DIR__.'/../php/includes/authenticator_backup_codes.php';
function check($value,$message){if(!$value)throw new RuntimeException($message);}
$code='A1B2-C3D4-E5F6-7890-ABCD';check(strlen(sigmaBackupCodeHash($code))===64,'Codes are hashed');check(sigmaBackupCodeHash(strtolower($code))===sigmaBackupCodeHash($code),'Case insensitive');check(sigmaBackupCodeHash(str_replace('-',' ',$code))===sigmaBackupCodeHash($code),'Spacing normalized');foreach(['','123456','A1B2-C3D4-E5F6-7890-ABCZ',str_repeat('A',21)] as $bad)check(sigmaBackupCodeHash($bad)==='','Reject malformed codes');
$auth=file_get_contents(__DIR__.'/../php/api/auth.php');$start=strpos($auth,"['generate_backup_codes','recover_2fa']");$end=strpos($auth,'// ── POST: SETUP 2FA',$start);$recovery=substr($auth,$start,$end-$start);
check(strpos($recovery,'sigmaRequireOwnIdentity')<strpos($recovery,'sigmaConsumeBackupCode'),'Recovery requires the password-verified account challenge');check(str_contains($recovery,'password_verify')&&str_contains($recovery,'FOR UPDATE'),'Verify password and serialize concurrent recovery');check(str_contains($recovery,'TotpService::verifyCode'),'Issuing new backup codes requires current TOTP');check(str_contains($recovery,'sigmaRevokeAccountSessions'),'Recovery revokes sessions');check(str_contains($recovery,"'Google Authenticator 2FA reset'"),'Recovery reset is authenticated-audited');check(str_contains($recovery,"'Authenticator backup-code recovery failed'"),'Failed recovery is audited');check(str_contains($recovery,'sigmaTwoFactorRateLimit'),'Recovery is rate limited');
foreach(explode("\n",$recovery) as $line)if(str_contains($line,'sigmaRecordAuthentication'))check(!str_contains($line,"['password']")&&!str_contains($line,"['backupCode']")&&!str_contains($line,"['totp_secret']"),'Audit records must not include credentials');
echo "PASS backup-code normalization, challenge/password/TOTP requirements, serialized recovery, session revocation, rate limits and credential-free authentication logs.\n";
